// Verifies the HMAC Convex puts on every call: sha256(timestamp.METHOD.path.rawBody).
// The secret comes from the environment, never from this workflow.
const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const PATH = '/webhook/lendloop-loan-events';
const TOLERANCE_MS = 5 * 60 * 1000;

const item = $input.first();
const headers = item.json.headers || {};
const ts = headers['x-lendloop-timestamp'];
const sig = headers['x-lendloop-signature'] || '';

let raw = JSON.stringify(item.json.body ?? {});
if (item.binary && item.binary.data && item.binary.data.data) {
  raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
}

let valid = Boolean(secret && ts && sig) && Math.abs(Date.now() - Number(ts)) <= TOLERANCE_MS;
if (valid) {
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.POST.${PATH}.${raw}`).digest('hex');
  valid = expected.length === sig.length && crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sig));
}

const event = valid ? JSON.parse(raw) : null;
return [{ json: { valid, event } }];

// Mock channel: logs the message instead of emailing. Swap this node for an
// email/Slack node in production. Only the fields needed for the message are used.
const e = $input.first().json.event;
const lines = {
  pending: `${e.toolName}: you have a new borrow request for ${e.startDate} to ${e.endDate}.`,
  approved: `${e.toolName}: your request for ${e.startDate} to ${e.endDate} was approved.`,
  declined: `${e.toolName}: your request for ${e.startDate} to ${e.endDate} was declined.`,
  cancelled: `${e.toolName}: a borrow request was cancelled.`,
  returned: `${e.toolName}: the loan is closed. Thanks for returning it!`,
  return_reported: `${e.toolName}: the borrower says it is back. Please confirm the return.`,
  return_disputed: `${e.toolName}: the owner has not received it yet. Please get in touch.`,
};
const message = { to: e.recipient.email, name: e.recipient.name, text: lines[e.status] ?? `${e.toolName}: status ${e.status}` };
console.log('[LendLoop notification]', JSON.stringify(message));
return [{ json: { eventKey: e.eventKey, loanId: e.loanId, status: e.status, channel: 'mock' } }];

const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const PATH = '/n8n/events';
const n = $input.first().json;
// eventKey is unique per state change, so Convex ignores duplicates from retries.
const body = JSON.stringify({
  eventKey: `notified:${n.eventKey}`,
  kind: 'notification_sent',
  loanId: n.loanId,
  detail: `Notified about "${n.status}" via ${n.channel}`,
});
const ts = String(Date.now());
const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.POST.${PATH}.${body}`).digest('hex');
return [{ json: { body, ts, sig } }];
